function A([bool]$x,[string]$m){if(!$x){throw $m}}
function O([string]$t,[string[]]$v,[string]$n){$p=-1;foreach($x in $v){$q=$t.IndexOf($x,$p+1);A ($q-gt$p) "$n $x";$p=$q}}
function V([string]$m,[string]$s,[string]$h,[string]$t){
 $b=$m.IndexOf('#define LOADER_PERSISTENT_STATUS_MAX_CONTEXTS');$e=$m.IndexOf('static LOADER_PERSISTENT_STATUS_PROOF QueryPersistentDetachedStatus');A ($b-ge0-and$e-gt$b) 'query section';$all=$m.Substring($b,$e-$b)
