}
$m=[IO.File]::ReadAllText((Resolve-Path $MainPath));$s=[IO.File]::ReadAllText((Resolve-Path $ServicePath));$h=[IO.File]::ReadAllText((Resolve-Path $HeaderPath));$t=[IO.File]::ReadAllText((Resolve-Path $TestPath));V $m $s $h $t
